  $plrt${"title":"Somme des racines","description":"x₁ + x₂ = −b/a sans calculer les racines","variations":[{"blanks":[{"expectedAnswer":"{{eval:-b}}"}],"statement":"Le polynôme $P(x)={{eval:ax^2+bx+c}}$ a deux racines $x_1$ et $x_2$. Sans les calculer, détermine leur somme.\n\n$x_1+x_2=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"1"},{"name":"b","expression":"1..9;±"},{"name":"c","expression":"1..9;±"}],"conditions":["b^2-4*a*c > 0"],"correction":{"steps":["Le discriminant vaut $\\Delta={{eval:b;()}}^2-4\\times{{eval:a;()}}\\times{{eval:c;()}}={{eval:b^2-4*a*c}}>0$ : les deux racines existent.","Quand un trinôme $ax^2+bx+c$ a deux racines, $x_1+x_2=-\\dfrac{b}{a}$.","Ici $a=1$ : $x_1+x_2=-b={{eval:-b}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:-b/a}}"}],"statement":"Le polynôme $P(x)={{eval:ax^2+bx+c}}$ a deux racines $x_1$ et $x_2$. Sans les calculer, détermine leur somme.\n\n$x_1+x_2=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"2..5;±"},{"name":"b","expression":"1..9;±"},{"name":"c","expression":"1..9;±"}],"conditions":["b^2-4*a*c > 0"],"correction":{"steps":["Le discriminant vaut $\\Delta={{eval:b;()}}^2-4\\times{{eval:a;()}}\\times{{eval:c;()}}={{eval:b^2-4*a*c}}>0$ : les deux racines existent.","Quand un trinôme $ax^2+bx+c$ a deux racines, $x_1+x_2=-\\dfrac{b}{a}$.","$$x_1+x_2=-\\dfrac{b}{a}=\\dfrac{ {{eval:-b}} }{ {{a}} }={{eval:-b/a}}$$"]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["5"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-5","c":"3"},"description":"x^2-5x+3 : S=5, P=3","variationIndex":0},{"answers":["-5"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-5","c":"3"},"description":"S = b (signe oublié)","variationIndex":0},{"answers":["3"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-5","c":"3"},"description":"produit donné pour la somme","variationIndex":0},{"answers":["-3"],"expected":{"status":"correct"},"variab