insert into _plrt_modeles values ('70e682f9-9f54-495b-8943-69c8597a5c32', $plrt$Suites$plrt$, $plrt$Modèles d'évolution$plrt$, null, array['1_SPE'], 'draft',
  $plrt${"title":"Intérêts simples ou composés : la suite est-elle arithmétique ?","description":"Reconnaître une suite arithmétique dans un placement (intérêts simples), ou non","variations":[{"statement":"On place ${{C}}$ € à **intérêts simples** au taux annuel de ${{t}}\\,\\%$ : chaque année, on ajoute au capital ${{t}}\\,\\%$ du capital **initial**. On note $u_n$ le capital (en €) au bout de $n$ années.\n\nLa suite $(u_n)$ est-elle arithmétique ?","variables":[{"name":"k","expression":"5..50"},{"name":"C","expression":"eval:100*k"},{"name":"t","expression":"1..6"}],"correction":{"steps":["Chaque année, on ajoute la même somme : ${{t}}\\,\\%$ de ${{C}}$ €, soit $\\dfrac{ {{t}} }{100}\\times{{C}}={{eval:C*t/100}}$ €.","Pour tout $n$ : $u_{n+1}=u_n+{{eval:C*t/100}}$. La suite est **arithmétique** de raison ${{eval:C*t/100}}$."]},"correctChoiceIndex":["0"]},{"statement":"On place ${{C}}$ € à **intérêts composés** au taux annuel de ${{t}}\\,\\%$ : chaque année, les intérêts, égaux à ${{t}}\\,\\%$ du capital **de l'année**, s'ajoutent au capital. On note $u_n$ le capital (en €) au bout de $n$ années.\n\nLa suite $(u_n)$ est-elle arithmétique ?","variables":[{"name":"k","expression":"5..50"},{"name":"C","expression":"eval:100*k"},{"name":"t","expression":"1..6"}],"correction":{"steps":["Chaque année, les intérêts sont calculés sur le capital **de l'année**, qui augmente : on n'ajoute pas toujours la même somme.","$u_0={{C}}$, $u_1={{eval:C*(1+t/100);d}}$ et $u_2={{eval:C*(1+t/100)^2;d}}$ : $u_1-u_0={{eval:C*t/100;d}}$ mais $u_2-u_1={{eval:C*(1+t/100)*t/100;d}}$.","La suite n'est **pas arithmétique**."]},"correctChoiceIndex":["1"]},{"statement":"On place ${{C}}$ € sur un compte : chaque année, le capital augmente de ${{t}}\\,\\%$, puis la banque prélève ${{f}}$ € de frais. On note $u_n$ le capital (en €) au bout de $n$ années.\n\nLa suite $(u_n)$ est-elle arithmétique ?","variables":[{"name":"k","expression":"10..50"},{"name":"C","expression":"eval:100*k"},{"name":"t","expression":"1..6"},{"name":"f","expression":"10|15|20|25|30|40|50"},{"name":"a","expression":"eval:C*(1+t/100)-f"},{"name":"b","expression":"eval:a*(1+t/100)-f"}],"conditions":["f != C*t/100"],"correction":{"steps":["Pour tout $n$ : $u_{n+1}={{eval:1+t/100;d}}\\,u_n-{{f}}$.","$u_0={{C}}$, $u_1={{a}}$ et $u_2={{eval:b;d}}$.","$u_1-u_0={{eval:a-C}}$ et $u_2-u_1={{eval:b-a;d}}$ : les écarts ne sont pas constants, la suite n'est pas arithmétique."]},"correctChoiceIndex":["1"]}],"shared":{"choices":[{"content":"Oui, elle est arithmétique."},{"content":"Non, elle n'est pas arithmétique."}]},"test_specs":[{"expected":{"status":"correct"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v0 : « oui » accepté","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v0 : « non » refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v1 : « non » accepté","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v1 : « oui » refusé","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"C":"1000","a":"990","b":"979.8","f":"30","k":"10","t":"2"},"description":"v2 : « non » accepté","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"C":"1000","a":"990","b":"979.8","f":"30","k":"10","t":"2"},"description":"v2 : « oui » refusé","variationIndex":2,"selectedChoices":[0]}]}$plrt$::jsonb,
  $plrt${"title":"Intérêts simples ou composés : la suite est-elle arithmétique ?","description":"Reconnaître une suite arithmétique dans un placement (intérêts simples), ou non","variations":[{"statement":"On place ${{C}}$ € à **intérêts simples** au taux annuel de ${{t}}\\,\\%$ : chaque année, on ajoute au capital ${{t}}\\,\\%$ du capital **initial**. On note $u_n$ le capital (en €) au bout de $n$ années.\n\nLa suite $(u_n)$ est-elle arithmétique ?","variables":[{"name":"k","expression":"5..50"},{"name":"C","expression":"eval:100*k"},{"name":"t","expression":"1..6"}],"correction":{"steps":["Chaque année, on ajoute la même somme : ${{t}}\\,\\%$ de ${{C}}$ €, soit $\\dfrac{ {{t}} }{100}\\times{{C}}={{eval:C*t/100}}$ €.","Pour tout $n$ : $u_{n+1}=u_n+{{eval:C*t/100}}$. La suite est **arithmétique** de raison ${{eval:C*t/100}}$."]},"correctChoiceIndex":["0"]},{"statement":"On place ${{C}}$ € à **intérêts composés** au taux annuel de ${{t}}\\,\\%$ : chaque année, les intérêts, égaux à ${{t}}\\,\\%$ du capital **de l'année**, s'ajoutent au capital. On note $u_n$ le capital (en €) au bout de $n$ années.\n\nLa suite $(u_n)$ est-elle arithmétique ?","variables":[{"name":"k","expression":"5..50"},{"name":"C","expression":"eval:100*k"},{"name":"t","expression":"1..6"}],"correction":{"steps":["Chaque année, les intérêts sont calculés sur le capital **de l'année**, qui augmente : on n'ajoute pas toujours la même somme.","$u_0={{C}}$, $u_1={{eval:C*(1+t/100);d}}$ et $u_2={{eval:C*(1+t/100)^2;d}}$ : $u_1-u_0={{eval:C*t/100;d}}$ mais $u_2-u_1={{eval:C*(1+t/100)*t/100;d}}$.","La suite n'est **pas arithmétique**."]},"correctChoiceIndex":["1"]},{"statement":"On place ${{C}}$ € sur un compte : chaque année, le capital augmente de ${{t}}\\,\\%$, puis la banque prélève ${{f}}$ € de frais. On note $u_n$ le capital (en €) au bout de $n$ années.\n\nLa suite $(u_n)$ est-elle arithmétique ?","variables":[{"name":"k","expression":"10..50"},{"name":"C","expression":"eval:100*k"},{"name":"t","expression":"1..6"},{"name":"f","expression":"10|15|20|25|30|40|50"},{"name":"a","expression":"eval:C*(1+t/100)-f"},{"name":"b","expression":"eval:a*(1+t/100)-f"}],"conditions":["f != C*t/100"],"correction":{"steps":["Pour tout $n$ : $u_{n+1}={{eval:1+t/100;d}}\\,u_n-{{f}}$.","$u_0={{C}}$, $u_1={{a}}$ et $u_2={{eval:b;d}}$.","$u_1-u_0={{eval:a-C}}$ et $u_2-u_1={{eval:b-a;d}}$ : les écarts ne sont pas constants, la suite n'est **pas arithmétique**."]},"correctChoiceIndex":["1"]}],"shared":{"choices":[{"content":"Oui, elle est arithmétique."},{"content":"Non, elle n'est pas arithmétique."}]},"test_specs":[{"expected":{"status":"correct"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v0 : « oui » accepté","variationIndex":0,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v0 : « non » refusé","variationIndex":0,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v1 : « non » accepté","variationIndex":1,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"C":"2000","k":"20","t":"3"},"description":"v1 : « oui » refusé","variationIndex":1,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"C":"1000","a":"990","b":"979.8","f":"30","k":"10","t":"2"},"description":"v2 : « non » accepté","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"C":"1000","a":"990","b":"979.8","f":"30","k":"10","t":"2"},"description":"v2 : « oui » refusé","variationIndex":2,"selectedChoices":[0]}]}$plrt$::jsonb,
  null, null, null);
insert into _plrt_modeles values ('88a4432e-f4a6-4109-833d-9640cb0d225f', $plrt$Fonctions$plrt$, $plrt$Second degré$plrt$, $plrt$somme et produit des racines$plrt$, array['1_SPE'], 'draft',
  $plrt${"title":"Produit des racines","description":"x₁x₂ = c/a sans calculer les racines","variations":[{"blanks":[{"expectedAnswer":"{{c}}"}],"statement":"Le polynôme $P(x)={{eval:ax^2+bx+c}}$ a deux racines $x_1$ et $x_2$. Sans les calculer, détermine leur produit.\n\n$x_1\\times x_2=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"1"},{"name":"b","expression":"1..9;±"},{"name":"c","expression":"1..9;±"}],"conditions":["b^2-4*a*c > 0"],"correction":{"steps":["Le discriminant vaut $\\Delta={{eval:b;()}}^2-4\\times{{eval:a;()}}\\times{{eval:c;()}}={{eval:b^2-4*a*c}}>0$ : les deux racines existent.","Quand un trinôme $ax^2+bx+c$ a deux racines, $x_1\\times x_2=\\dfrac{c}{a}$.","Ici $a=1$ : $x_1\\times x_2=c={{c}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:c/a}}"}],"statement":"Le polynôme $P(x)={{eval:ax^2+bx+c}}$ a deux racines $x_1$ et $x_2$. Sans les calculer, détermine leur produit.\n\n$x_1\\times x_2=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"2..5;±"},{"name":"b","expression":"1..9;±"},{"name":"c","expression":"1..9;±"}],"conditions":["b^2-4*a*c > 0"],"correction":{"steps":["Le discriminant vaut $\\Delta={{eval:b;()}}^2-4\\times{{eval:a;()}}\\times{{eval:c;()}}={{eval:b^2-4*a*c}}>0$ : les deux racines existent.","Quand un trinôme $ax^2+bx+c$ a deux racines, $x_1\\times x_2=\\dfrac{c}{a}$.","$$x_1\\times x_2=\\dfrac{c}{a}=\\dfrac{ {{c}} }{ {{a}} }={{eval:c/a}}$$"]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["3"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-5","c":"3"},"description":"x^2-5x+3 : S=5, P=3","variationIndex":0},{"answers":["5"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-5","c":"3"},"description":"somme donnée pour le produit","variationIndex":0},{"answers":["-3"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-5","c":"3"},"description":"P = −c (signe)","variationIndex":0},{"answers":["-7"],"expected":{"status":"correct"},"variables":{"a":"1","b":"3","c":"-7"},"description":"x^2+3x-7 : S=−3, P=−7","variationIndex":0},{"answers":["\\frac{3}{2}"],"expected":{"status":"correct"},"variables":{"a":"2","b":"-7","c":"3"},"description":"2x^2-7x+3 : S=7/2, P=3/2","variationIndex":1},{"answers":["1{,}5"],"expected":{"status":"correct"},"variables":{"a":"2","b":"-7","c":"3"},"description":"décimaux exacts 3,5 et 1,5","variationIndex":1},{"answers":["3"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"-7","c":"3"},"description":"−b et c sans diviser par a","variationIndex":1},{"answers":["-\\frac{9}{4}"],"expected":{"status":"correct"},"variables":{"a":"-4","b":"6","c":"9"},"description":"-4x^2+6x+9 : S=3/2, P=−9/4","variationIndex":1},{"answers":["-\\frac{18}{8}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedFractions"]},"variables":{"a":"-4","b":"6","c":"9"},"description":"fraction non réduite 18/8","variationIndex":1}]}$plrt$::jsonb,
  $plrt${"title":"Produit des racines","description":"x₁x₂ = c/a sans calculer les racines","variations":[{"blanks":[{"expectedAnswer":"{{c}}"}],"statement":"Le polynôme $P(x)={{eval:ax^2+bx+c}}$ a deux racines $x_1$ et $x_2$. Sans les calculer, détermine leur produit.\n\n$x_1\\times x_2=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"1"},{"name":"b","expression":"1..9;±"},{"name":"c","expression":"1..9;±"}],"conditions":["b^2-4*a*c > 0"],"correction":{"steps":["Le discriminant vaut $\\Delta={{eval:b;()}}^2-4\\times{{eval:a;()}}\\times{{eval:c;()}}={{eval:b^2-4*a*c}}>0$ : les deux racines existent.","Quand un trinôme $ax^2+bx+c$ a deux racines, $x_1\\times x_2=\\dfrac{c}{a}$.","Ici $a=1$ : $x_1\\times x_2=c={{c}}$."]}},{"blanks":[{"expectedAnswer":"{{eval:c/a}}"}],"statement":"Le polynôme $P(x)={{eval:ax^2+bx+c}}$ a deux racines $x_1$ et $x_2$. Sans les calculer, détermine leur produit.\n\n$x_1\\times x_2=?$","variables":[{"name":"x","expression":"x|x"},{"name":"a","expression":"2..5;±"},{"name":"b","expression":"1..9;±"},{"name":"c","expression":"1..9;±"}],"conditions":["b^2-4*a*c > 0"],"correction":{"steps":["Le discriminant vaut $\\Delta={{eval:b;()}}^2-4\\times{{eval:a;()}}\\times{{eval:c;()}}={{eval:b^2-4*a*c}}>0$ : les deux racines existent.","Quand un trinôme $ax^2+bx+c$ a deux racines, $x_1\\times x_2=\\dfrac{c}{a}$.","$$x_1\\times x_2=\\dfrac{c}{a}=\\dfrac{ {{c}} }{ {{a}} }={{eval:c/a}}$$"]}}],"shared":{"blankDefaults":{"acceptDecimal":true}},"test_specs":[{"answers":["3"],"expected":{"status":"correct"},"variables":{"a":"1","b":"-5","c":"3"},"description":"x^2-5x+3 : P=3","variationIndex":0},{"answers":["5"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-5","c":"3"},"description":"somme donnée pour le produit","variationIndex":0},{"answers":["-3"],"expected":{"status":"incorrect"},"variables":{"a":"1","b":"-5","c":"3"},"description":"P = −c (signe)","variationIndex":0},{"answers":["-7"],"expected":{"status":"correct"},"variables":{"a":"1","b":"3","c":"-7"},"description":"x^2+3x-7 : P=−7","variationIndex":0},{"answers":["\\frac{3}{2}"],"expected":{"status":"correct"},"variables":{"a":"2","b":"-7","c":"3"},"description":"2x^2-7x+3 : P=3/2","variationIndex":1},{"answers":["1{,}5"],"expected":{"status":"correct"},"variables":{"a":"2","b":"-7","c":"3"},"description":"décimal exact 1,5","variationIndex":1},{"answers":["3"],"expected":{"status":"incorrect"},"variables":{"a":"2","b":"-7","c":"3"},"description":"c sans diviser par a","variationIndex":1},{"answers":["-\\frac{9}{4}"],"expected":{"status":"correct"},"variables":{"a":"-4","b":"6","c":"9"},"description":"-4x^2+6x+9 : P=−9/4","variationIndex":1},{"answers":["-\\frac{18}{8}"],"expected":{"status":"unoptimal_form","constraintViolations":["reducedFractions"]},"variables":{"a":"-4","b":"6","c":"9"},"description":"fraction non réduite 18/8","variationIndex":1}]}$plrt$::jsonb,
