expected":{"status":"incorrect"},"variables":{"N":"5","a":"1","N1":"6","u0":"1","u1":"2","u2":"4","u3":"8"},"description":"v2 : « non » refusé","variationIndex":2,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"N":"6","a":"64","N1":"7","u0":"64","u1":"32","u2":"16","u3":"8"},"description":"v3 : « oui » accepté","variationIndex":3,"selectedChoices":[0]},{"expected":{"status":"incorrect"},"variables":{"N":"6","a":"64","N1":"7","u0":"64","u1":"32","u2":"16","u3":"8"},"description":"v3 : « non » refusé","variationIndex":3,"selectedChoices":[1]},{"expected":{"status":"correct"},"variables":{"N":"8","c":"4","d":"1","N1":"9","u0":"17","u1":"10","u2":"5","u3":"2"},"description":"v4 : « non » accepté","variationIndex":4,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"N":"8","c":"4","d":"1","N1":"9","u0":"17","u1":"10","u2":"5","u3":"2"},"description":"v4 : « oui » refusé","variationIndex":4,"selectedChoices":[0]},{"expected":{"status":"correct"},"variables":{"N":"6","c":"1","N1":"7","u0":"1","u1":"2","u2":"5","u3":"10"},"description":"v5 : « non » accepté","variationIndex":5,"selectedChoices":[1]},{"expected":{"status":"incorrect"},"variables":{"N":"6","c":"1","N1":"7","u0":"1","u1":"2","u2":"5","u3":"10"},"description":"v5 : « oui » refusé","variationIndex":5,"selectedChoices":[0]}]}$plrt$::jsonb,
